test_setup_files.behavior_test.js:
const assert = require('node:assert');
const { formatLog } = require('./logger.js');

const out = formatLog({
  method: 'POST',
  path: '/login',
  password: 'hunter2',
  headers: { Authorization: 'Bearer abc', 'x-request-id': 'r1' },
  user: { name: 'ada', apiKey: 'k-123' },
});
const obj = JSON.parse(out);

assert.strictEqual(obj.password, '[REDACTED]', 'top-level password not redacted');
assert.strictEqual(obj.headers.Authorization, '[REDACTED]', 'nested Authorization not redacted');
assert.strictEqual(obj.user.apiKey, '[REDACTED]', 'nested apiKey not redacted');

// non-sensitive fields preserved
assert.strictEqual(obj.method, 'POST');
assert.strictEqual(obj.headers['x-request-id'], 'r1');
assert.strictEqual(obj.user.name, 'ada');

// no secret VALUE may appear anywhere in the serialized log line
assert.ok(
  !out.includes('hunter2') && !out.includes('Bearer abc') && !out.includes('k-123'),
  'a secret value leaked into the log output'
);

console.log('ok');

reference_solution.logger.js:
const SENSITIVE = new Set(['password', 'token', 'authorization', 'secret', 'apikey']);

function redact(value) {
  if (Array.isArray(value)) {
    return value.map(redact);
  }
  if (value && typeof value === 'object') {
    const out = {};
    for (const [key, val] of Object.entries(value)) {
      out[key] = SENSITIVE.has(key.toLowerCase()) ? '[REDACTED]' : redact(val);
    }
    return out;
  }
  return value;
}

function formatLog(event) {
  return JSON.stringify(redact(event));
}

module.exports = { formatLog };

